'use strict';
const key='grid-study-v1';let tasks=[],filter='all',editing=null;
const $=s=>document.querySelector(s),form=$('#form'),dialog=$('#editor');
function notify(message){$('#notice').textContent=message;$('#notice').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').style.display='none',3500)}
function valid(t){return t&&typeof t.id==='string'&&typeof t.title==='string'&&typeof t.subject==='string'&&typeof t.date==='string'&&['normal','high','low'].includes(t.priority)&&typeof t.done==='boolean'}
try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved)&&saved.every(valid))tasks=saved;else notify('Сохранённые данные имеют неверный формат')}catch{notify('Не удалось прочитать сохранённые задачи')}
function save(){try{localStorage.setItem(key,JSON.stringify(tasks))}catch{notify('Не удалось сохранить данные. Сделай экспорт перед закрытием.')}render()}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function openEditor(task){editing=task?.id||null;form.reset();$('#form-title').textContent=task?'Изменить задачу':'Новая задача';if(task)for(const name of ['title','subject','date','priority'])form.elements[name].value=task[name];dialog.showModal();form.elements.title.focus()}
$('#new').onclick=()=>openEditor();$('#close').onclick=()=>dialog.close();
form.onsubmit=e=>{e.preventDefault();const title=form.elements.title.value.trim();if(!title){form.elements.title.setCustomValidity('Введите название задачи');form.elements.title.reportValidity();return}const data={title,subject:form.elements.subject.value.trim(),date:form.elements.date.value,priority:form.elements.priority.value};if(editing)Object.assign(tasks.find(t=>t.id===editing),data);else tasks.push({...data,id:(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),done:false});save();dialog.close()};form.elements.title.oninput=()=>form.elements.title.setCustomValidity('');
for(const b of document.querySelectorAll('[data-filter]'))b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});render()};$('#search').oninput=render;
function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node}
function render(){const done=tasks.filter(t=>t.done).length,late=tasks.filter(t=>!t.done&&t.date&&t.date<today()).length,percent=tasks.length?Math.round(done/tasks.length*100):0;$('#total').textContent=tasks.length;$('#active').textContent=tasks.length-done;$('#done').textContent=done;$('#late').textContent=late;$('#percent').textContent=percent+'%';$('.ring').style.setProperty('--progress',percent+'%');$('#progress-caption').textContent=tasks.length?`${done} из ${tasks.length} задач выполнено`:'Твой следующий шаг начинается здесь';const query=$('#search').value.toLocaleLowerCase();const visible=tasks.filter(t=>(filter==='all'||(filter==='done'?t.done:!t.done))&&(t.title+' '+t.subject).toLocaleLowerCase().includes(query)).sort((a,b)=>Number(a.done)-Number(b.done)||(a.date||'9999').localeCompare(b.date||'9999'));$('#count').textContent=String(visible.length).padStart(2,'0');const list=$('#tasks');list.replaceChildren();if(!visible.length){const box=el('div','empty');box.append(el('div','symbol','◇'),el('h3','',tasks.length?'Здесь пока нет задач':'Чистый лист. Новая цель.'),el('p','',tasks.length?'Измени фильтр или поисковый запрос.':'Добавь первое задание — и начни свой учебный маршрут.'));if(!tasks.length){const b=el('button','','＋ Добавить первую задачу');b.onclick=()=>openEditor();box.append(b)}list.append(box)}for(const t of visible){const row=el('article','task'+(t.done?' completed':'')),check=el('input','check');check.type='checkbox';check.checked=t.done;check.setAttribute('aria-label','Выполнено: '+t.title);check.onchange=()=>{t.done=check.checked;save()};const info=el('div','task-info'),meta=el('div','task-meta');meta.append(el('span','',t.subject||'Без предмета'));if(t.date){const overdue=!t.done&&t.date<today();meta.append(el('span',overdue?'overdue':'',(overdue?'Срок прошёл · ':'До ')+t.date.split('-').reverse().join('.')))}info.append(el('div','task-title',t.title),meta);const badge=el('span','badge '+t.priority,{high:'Высокий',normal:'Обычный',low:'Низкий'}[t.priority]),actions=el('div','actions'),edit=el('button','','✎'),remove=el('button','','×');edit.setAttribute('aria-label','Изменить: '+t.title);edit.onclick=()=>openEditor(t);remove.setAttribute('aria-label','Удалить: '+t.title);remove.onclick=()=>{if(confirm('Удалить задачу «'+t.title+'»?')){tasks=tasks.filter(x=>x.id!==t.id);save()}};actions.append(edit,remove);row.append(check,info,badge,actions);list.append(row)}}
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(tasks,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='grid-study-tasks.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Задачи экспортированы')};render();
